/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Header tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustActivityStatementTmp))]
public METCustActivityStatementTmp getHeader()
{
    select custTransListingTmp;
    return custTransListingTmp;
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Payment lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustActivityStatementPaymentLinesTmp))]
public METCustActivityStatementPaymentLinesTmp getPaymentLines()
{
    select custTransListingPaymentLinesTmp;
    return custTransListingPaymentLinesTmp;
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustActivityStatementInvoiceLinesTmp))]
public METCustActivityStatementInvoiceLinesTmp getInvoiceLines()
{
    select custActivityStatementInvoiceLinesTmp;
    return custActivityStatementInvoiceLinesTmp;
}

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Process report data.
    /// </summary>
    public void processReport()
    {
        contract = this.parmDataContract() as METCustActivityStatementContract;

        //HEADER
        this.populateHeader();
        
        //Ledger Journal lines
        this.populateLedgerLines();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Populates header tmp table
    /// </summary>
    public void populateHeader()
    {
        CustTable               custTable;
        CompanyInfo             companyInfo;
        str                     communityChestDataArea = METConstants::CommunityChestLegalEntityId;

        companyInfo                                 = CompanyInfo::find();
        ttsbegin;
        custTransListingTmp.CompanyCoRegNum         = companyInfo.CoRegNum;
        custTransListingTmp.LinkedCustAccountNum    = contract.parmCSAccountNum();
        custTransListingTmp.LinkedLegalEntity       = companyInfo.DataArea;
        changecompany(contract.parmCSLegalEntity())
        {
            custTable = CustTable::find(contract.parmCSAccountNum());
            Image img = CustTable::metGetCustReportLogo(custTransListingTmp.LinkedCustAccountNum);
            if(img != null)
            {
                custTransListingTmp.CompanyLogo = img.getData();
            }
            else
            {
                custTransListingTmp.CompanyLogo = CompanyImage::findByRecord(CompanyInfo::find()).Image;
            }
            custTransListingTmp.CustName            = CustTable.name();
            custTransListingTmp.CustTable_Address   = DirUtility::replaceAddressTokenLanguage(custTable.statementAddress(), custTable.languageId());
            custTransListingTmp.Currency            = custTable.Currency;
            custTransListingTmp.KnownAs             = DirPartyTable::findRec(custTable.party).KnownAs;
        }
        custTransListingTmp.ToDate                  = contract.parmToDate();
        custTransListingTmp.FromDate                = contract.parmFromDate();
        custTransListingTmp.CompanyAddress          = companyInfo.postalAddress().Address;
        if (curExt() == communityChestDataArea)
        {
            if (custTable.balanceAllCurrency() < 0)
            {
                custTransListingTmp.Balance             = -custTable.balanceAllCurrency();
            }
            else 
            {
                custTransListingTmp.Balance             = custTable.balanceAllCurrency();
            }
        }
        custTransListingTmp.FooterNote              = contract.parmFooterNote();
        custTransListingTmp.insert();
        ttscommit;
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Populates payment and transactions lines
    /// </summary>
    public void populateLedgerLines()
    {       
        // Payment lines
        this.paymentLines();

        // Invoice and trans lines
        this.invoiceLines();        
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Payment lines populate tmp table
    /// </summary>
    public void paymentLines()
    {
        Query                   query;
        QueryBuildDataSource    qbdsMETCustTable, qbdscustTable, qbdscustTrans;
        Map                     targetToSourceMap;

        query = new Query();

        qbdsMETCustTable        = query.addDataSource(tableNum(METCustTable));
        qbdsMETCustTable.fields().dynamic(0);
        qbdsMETCustTable.fields().clearFieldList();

        qbdscustTable           = qbdsMETCustTable.addDataSource(tableNum(CustTable));
        qbdscustTable.relations(false);
        qbdscustTable.addLink(fieldNum(METCustTable, AccountNum), fieldNum(CustTable, AccountNum));
        qbdscustTable.addSelectionField(fieldNum(CustTable, AccountNum));
        qbdscustTable.fields().dynamic(0);

        qbdscustTrans           = qbdscustTable.addDataSource(tableNum(CustTrans));
        qbdscustTrans.relations(false);
        qbdscustTrans.addLink(fieldNum(CustTable, AccountNum), fieldNum(CustTrans, AccountNum));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, TransDate));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, Txt));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, PaymReference));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, Invoice));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, AmountCur));
        qbdscustTrans.addSelectionField(fieldNum(CustTrans, TransType));
        qbdscustTrans.fields().dynamic(0);


        // Add required ranges
        qbdsMETCustTable.addRange(fieldNum(METCustTable, CSAccountNum)).value(contract.parmCSAccountNum());
        qbdsMETCustTable.addRange(fieldNum(METCustTable, CSLegalEntity)).value(contract.parmCSLegalEntity());
        qbdscustTrans.addRange(fieldNum(CustTrans, TransDate)).value(queryRange(contract.parmFromDate(), contract.parmToDate()));
        qbdscustTrans.addRange(fieldNum(CustTrans, TransType)).value(enum2Str(LedgerTransType::Payment));

        targetToSourceMap = new Map(Types::String, Types::Container);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, AccountNum),      [qbdscustTable.uniqueId(), fieldStr(CustTable, AccountNum)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, TransDate),       [qbdscustTrans.uniqueId(), fieldStr(CustTrans, TransDate)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, Txt),             [qbdscustTrans.uniqueId(), fieldStr(CustTrans, Txt)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, PaymReference),   [qbdscustTrans.uniqueId(), fieldStr(CustTrans, PaymReference)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, Invoice),         [qbdscustTrans.uniqueId(), fieldStr(CustTrans, Invoice)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, AmountCur),       [qbdscustTrans.uniqueId(), fieldStr(CustTrans, AmountCur)]);
        targetToSourceMap.insert(fieldStr(METCustActivityStatementPaymentLinesTmp, TransType),       [qbdscustTrans.uniqueId(), fieldStr(CustTrans, TransType)]);
         

        Query::insert_recordset(custTransListingPaymentLinesTmp, targetToSourceMap, query);
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Populates invoice lines tmp table
    /// </summary>
    public void invoiceLines()
    {
        METCustTable    metCustTable;
        CustTrans       custTrans;
        date            paramFromDate, paramToDate;
        AccountNum      associatedAccount;
        DataAreaId      legalEntity;

        paramFromDate       = contract.parmFromDate();
        paramToDate         = contract.parmToDate();
        associatedAccount   = contract.parmCSAccountNum();
        legalEntity         = contract.parmCSLegalEntity();

        while select 
            AccountNum,
            CSAccountNum,
            CSLegalEntity
        from 
            metCustTable
        join 
            TransDate,
            Txt,
            PaymReference,
            Invoice,
            AmountCur,
            TransType,
            Voucher
        from 
            custTrans
        where 
            metCustTable.AccountNum == custTrans.AccountNum
            && metCustTable.CSAccountNum == associatedAccount
            && metCustTable.CSLegalEntity == legalEntity
            && custTrans.TransDate >= paramFromDate
            && custTrans.TransDate <= paramToDate
            && custTrans.TransType != LedgerTransType::Payment
            && custTrans.TransType != LedgerTransType::Settlement
        {
            ttsbegin;
            custActivityStatementInvoiceLinesTmp.accountNum      = metCustTable.AccountNum;
            custActivityStatementInvoiceLinesTmp.TransDate       = custTrans.TransDate;
            custActivityStatementInvoiceLinesTmp.Txt             = custTrans.Txt;
            custActivityStatementInvoiceLinesTmp.PaymReference   = custTrans.PaymReference;
            custActivityStatementInvoiceLinesTmp.Invoice         = custTrans.Invoice;
            custActivityStatementInvoiceLinesTmp.AmountCur       = custTrans.AmountCur;
            custActivityStatementInvoiceLinesTmp.TransType       = custTrans.TransType;
            custActivityStatementInvoiceLinesTmp.GST             = this.calculateGST(custTrans.Voucher, custTrans.TransDate);
            custActivityStatementInvoiceLinesTmp.TaxAmountCur    = custTrans.AmountCur - custActivityStatementInvoiceLinesTmp.GST;
            custActivityStatementInvoiceLinesTmp.insert();
            ttscommit;
        }
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Calculates GST per trans line according to report parameter
    /// </summary>
    /// <param name = "_voucher">cust voucher</param>
    /// <param name = "_transDate">cust trans date</param>
    /// <returns>total gst</returns>
    public TaxAmountCur calculateGST(Voucher _voucher, TransDate _transDate)
    {
        TaxTrans        taxTrans;
        TaxAmountCur    calcGST;
        List            list  = new List(Types::String);
        ListEnumerator  enumerator;
        str             TaxCode;

        List = contract.parmSalesTaxCode();
        enumerator = list.getEnumerator();
        enumerator.reset();
        while(enumerator.moveNext())
        {
            taxCode = enumerator.current();

            select firstonly 
                taxAmountCur,
                Voucher,
                TransDate,
                TaxCode
            from 
                taxTrans
            where 
                    taxTrans.Voucher    == _voucher
                 && taxTrans.TransDate  == _transDate
                 && taxTrans.TaxCode    == taxCode;

            calcGST = calcGST + (-taxTrans.taxAmountCur);
                
        }

        return calcGST;

    }
